 const PixelFont& font_;const Skin& skin_;const Skin& icons_;Document& document_;std::function<ReferenceSession&()> session_;std::string windowId_;
 std::array<PixelButton*,9> buttons_{};gfx::Rect imageBox_;gfx::Point dragStart_;ReferencePoint panStart_;bool panning_=false,sampling_=false,secondary_=false,pasting_=false;std::uint64_t gestureIdentity_=0;
 struct Cache {std::shared_ptr<const std::vector<Pixel>> source;os::SurfaceRef normal,gray;};std::unordered_map<std::string,Cache> caches_;SkBitmap checker_;gfx::Color checkerA_=0,checkerB_=0;
 const ReferenceImage* image(){auto& session=session_();session.synchronize(document_.referenceImages());const auto id=session.selected(windowId_);const auto& images=document_.referenceImages();const auto it=std::find_if(images.begin(),images.end(),[&](const auto& i){return i.id==id;});return it==images.end()?nullptr:&*it;}
