 gfx::Rect destination(const ReferenceImage& image,ReferenceView& view){const double z=scale(image,view);const int x=imageBox_.x+int(std::floor((double(imageBox_.w)-image.width*z*uiScale)/2+view.pan.x*uiScale+.5)),y=imageBox_.y+int(std::floor((double(imageBox_.h)-image.height*z*uiScale)/2+view.pan.y*uiScale+.5));return {x,y,std::max(1,int(std::floor(image.width*z*uiScale+.5))),std::max(1,int(std::floor(image.height*z*uiScale+.5)))};}
