 void sample(gfx::Point position){auto source=image();auto state=view();if(!source||!state||!imageBox_.contains(position))return;const auto to=destination(*source,*state);auto color=sampleReference(*source,to.x,to.y,scale(*source,*state)*uiScale,{double(position.x),double(position.y)});if(color&&sampled)sampled(*color,secondary_);}
 void paste(){if(pasting_)return;pasting_=true;sync();const auto identity=document_.identity();try{auto source=readClipboard?readClipboard():std::optional<SelectionClipboard>{};if(identity==document_.identity()){if(!source){if(error)error(U"剪贴板中没有图像像素");}else if(windowId_.empty()||session_().window(windowId_)){static std::uint64_t serial=0;ReferenceImage item;do{item.id="reference-native-"+std::to_string(identity)+"-"+std::to_string(++serial);}while(std::any_of(document_.referenceImages().begin(),document_.referenceImages().end(),[&](const auto& image){return image.id==item.id;}));item.width=source->width;item.height=source->height;item.pixels=std::make_shared<const std::vector<Pixel>>(std::move(source->pixels));validateReferenceImage(item);const auto id=item.id;document_.addReferenceImage(std::move(item));session_().synchronize(document_.referenceImages());session_().chooseAdded(id,windowId_);}}}catch(const std::exception& e){if(error)error(U"无法粘贴参考图："+unicodeText(e.what()));}pasting_=false;notify();}
